    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    original=[row[:] for row in g]
    markers=[(r,c,original[r][c]) for r in range(h) for c in range(w) if original[r][c] not in (0,1)]
    for mr,mc,color in markers:
        # Associate marker with the contiguous 1-component touching it.
        starts=[(r,c) for r in range(max(0,mr-1),min(h,mr+2)) for c in range(max(0,mc-1),min(w,mc+2)) if original[r][c]==1]
        comp=set(); stack=starts[:]
        while stack:
            p=stack.pop()
            if p in comp: continue
            comp.add(p); r,c=p
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(r+dr,c+dc)
                if 0<=q[0]<h and 0<=q[1]<w and original[q[0]][q[1]]==1 and q not in comp:
                    stack.append(q)
        # Recolor each complete 2x2 block of foreground in that component.
        for r,c in comp:
            if (r+1,c) in comp and (r,c+1) in comp and (r+1,c+1) in comp:
                g[r][c]=g[r+1][c]=g[r][c+1]=g[r+1][c+1]=color
    return g

